Layout.Stylesheet:
body { margin: 0; font-size: 9pt; }
div { margin: 5pt; padding: 5pt; border-style: solid; border-width: 2pt; }
.red { border-color: red; }
.hex { border-color: #00ff00; }
.rgb { border-color: rgb(0, 0, 255); }
.mixed { border-top-color: red; border-right-color: green; border-bottom-color: blue; border-left-color: yellow; }
.current { color: purple; border-color: currentcolor; }
